using MediaBrowser.Common.Configuration;
using PersonCleaner.Storage;
using SQLitePCL.pretty;
using SQLitePCLEx;
using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.Linq;
using System.Threading;

namespace PersonCleaner.Housekeeping
{
    public sealed class HousekeepingResultRow
    {
        public long ProposalId { get; set; }
        public long EmbyPersonId { get; set; }
        public string Person { get; set; }
        public string Recommendation { get; set; }
        public string SignalType { get; set; }
        public string Provider { get; set; }
        public string CurrentValue { get; set; }
        public string ProposedValue { get; set; }
        public string CurrentEmbyIds { get; set; }
        public string ProposedEmbyIds { get; set; }
        public string CurrentName { get; set; }
        public string ProposedName { get; set; }
        public string CurrentTmdbIds { get; set; }
        public string ProposedTmdbIds { get; set; }
        public string CurrentTvdbIds { get; set; }
        public string ProposedTvdbIds { get; set; }
        public string CurrentImdbIds { get; set; }
        public string ProposedImdbIds { get; set; }
        public string LinkedMediaEvidence { get; set; }
        public double Confidence { get; set; }
        public int LinkedMedia { get; set; }
        public int CheckedMedia { get; set; }
        public string Evidence { get; set; }
        public string ReviewStatus { get; set; }
    }

    internal sealed class HousekeepingRepository : IDisposable
    {
        private const int BatchSize = 1000;
        private readonly IDatabaseConnection db;

        public HousekeepingRepository(IApplicationPaths paths)
            : this(ArchiveDatabase.ResolvePath(paths))
        {
        }

        internal HousekeepingRepository(string path)
        {
            ArchiveDatabase.RequireExisting(path);
            db=SQLite3.Open(path,ConnectionFlags.ReadWrite|ConnectionFlags.PrivateCache|ConnectionFlags.NoMutex,null,new Dictionary<string,delegate_collation>(),new Dictionary<Tuple<string,int>,Action<IReadOnlyList<sqlite3_value>,sqlite3_context>>(),true,false);
            db.Execute("PRAGMA busy_timeout=5000"); db.Execute("PRAGMA synchronous=NORMAL");
            ArchiveDatabase.ValidateObjects(db,"housekeeping v3","housekeeping_run","housekeeping_signal","housekeeping_recommendation","truth_entity_delta","truth_identity_delta","truth_relationship_delta","housekeeping_latest_results","provider_identity_issue");
            ArchiveDatabase.ValidateMigrations(db,6);
        }

        public long Run(DateTime cutoff,CancellationToken token,Action<string,double,TimeSpan> report)
        {
            var clock=Stopwatch.StartNew(); long run=0;
            using(token.Register(()=>{try{db.Interrupt();}catch{}})) try
            {
                Phase(token,report,clock,"Creating experiment run",1); run=StartRun(cutoff);
                Phase(token,report,clock,"Normalizing provider identity status",4);
                Tx(x=>{IdentitySignals(x,run);MissingIdentitySignals(x,run);State(x,run,"provider-identity-status",5);});
                Phase(token,report,clock,"Auditing every current identity against linked media",5);Tx(x=>{UniversalIdentityAudits(x,run);State(x,run,"universal-identity-audit",10);});
                Phase(token,report,clock,"Building retained candidate/media evidence ledger",10);Tx(x=>{RelationshipSignals(x,run);State(x,run,"identity-and-relationship-evidence",14);});
                Reacquire("tmdb",run,token,report,clock,14,24);
                Reacquire("tvdb",run,token,report,clock,24,48);
                Phase(token,report,clock,"Evaluating media-backed TMDB replacements",48);Tx(x=>{MediaBackedTmdbReplacements(x,run);State(x,run,"media-backed-tmdb-replacements",49);});
                Phase(token,report,clock,"Evaluating retained provider candidates and Emby ownership",49);Tx(x=>{CandidateDecisions(x,run);State(x,run,"candidate-decisions",51);});
                Phase(token,report,clock,"Retaining universal identity-audit findings for case evidence",51);Tx(x=>State(x,run,"universal-audit-evidence",52));
                Phase(token,report,clock,"Finding provider identity issues",52);Tx(x=>{ProviderIssues(x,run);State(x,run,"provider-identity-issues",53);});
                Phase(token,report,clock,"Withholding or confirming unavailable-ID removals",53);Tx(x=>{UnavailableExplicit(x,run);State(x,run,"identity-decisions",54);});
                Phase(token,report,clock,"Evaluating provider renames from aggregated audit evidence",54);
                Tx(x=>{RenamesV3(x,run);State(x,run,"provider-renames",66);});
                Phase(token,report,clock,"Finding merge evidence",66);
                Tx(x=>{Merges(x,run);State(x,run,"merge-evidence",72);});
                Phase(token,report,clock,"Finding cross-provider split evidence",72);Tx(x=>{CrossProviderSplits(x,run);State(x,run,"cross-provider-split-evidence",78);});
                Phase(token,report,clock,"Finding same-provider linked-media partitions",78);Tx(x=>{SplitsV2(x,run);State(x,run,"split-evidence",84);});
                Phase(token,report,clock,"Consolidating detector findings into actionable review cases",84);Tx(x=>{ConsolidateReviewCases(x,run);State(x,run,"review-case-consolidation",90);});
                Phase(token,report,clock,"Creating delta truth",90); Tx(x=>DeltaTruth(x,run));
                Phase(token,report,clock,"Finalizing results",96); Tx(x=>Complete(x,run));
                token.ThrowIfCancellationRequested(); return run;
            }
            catch(SQLiteException) when(token.IsCancellationRequested){if(run!=0)Stop(run,"cancelled","SQLite interrupted by Emby cancellation");throw new OperationCanceledException("Housekeeping cancelled",token);}
            catch(OperationCanceledException){if(run!=0)Stop(run,"cancelled","Cancelled by Emby");throw;}
            catch(Exception ex){if(run!=0)Stop(run,"failed",ex.ToString());throw;}
        }

        private long StartRun(DateTime cutoff)
        {
            long id=0; var now=Now(); Tx(x=>{
                x.Execute("INSERT OR IGNORE INTO algorithm(name,version,code_hash,configuration_json) VALUES('person-housekeeping','normalized-v9','normalized-v9-actionable-review-cases','{\"humanReview\":true,\"deltaTruth\":true,\"batchSize\":1000,\"anchor\":\"emby-person-linked-media\",\"universalProviderAudit\":true,\"evidenceGapAcquisition\":true,\"relationshipEvidenceLedger\":true,\"providerIssues\":true,\"supportedExternalIdDiscovery\":true,\"anchoredProviderIssues\":true,\"configurableNameEquivalence\":true,\"providerConsensusRename\":true,\"actionableReviewCases\":true,\"providerMisattributionAdjudication\":true}')");
                Exec(x,"INSERT INTO experiment_run(algorithm_id,truth_id,observation_cutoff_utc,mask_policy_json,started_utc,status) SELECT algorithm_id,1,@cutoff,json_object('providerRequests','bounded-cached-evidence-gaps','auditScope','all-linked-emby-people-both-providers','givenNameEquivalences',@names),@now,'running' FROM algorithm WHERE name='person-housekeeping' AND version='normalized-v9'",s=>{s.TryBind("@cutoff",cutoff.ToString("o"));s.TryBind("@names",Plugin.Instance.Configuration.GivenNameEquivalences??string.Empty);s.TryBind("@now",now);}); id=LastId(x);
                Exec(x,"INSERT INTO housekeeping_run(run_id,algorithm_version,base_truth_id,phase,progress,status,observation_cutoff_utc,started_utc,heartbeat_utc) VALUES(@run,'normalized-v9',1,'starting',1,'running',@cutoff,@now,@now)",s=>{s.TryBind("@run",id);s.TryBind("@cutoff",cutoff.ToString("o"));s.TryBind("@now",now);});}); return id;
        }

        private static void IdentitySignals(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,candidate_external_id,current_name,candidate_name,score,confidence,evidence_text,created_utc)
SELECT @run,p.emby_id,'emby:'||p.emby_id,'tmdb',CASE r.provenance WHEN 'direct' THEN 'identity-live' WHEN 'direct-unavailable' THEN 'identity-unavailable' ELSE 'identity-unresolved' END,p.tmdb_id,r.resolved_tmdb_id,p.name,e.name,CASE r.provenance WHEN 'direct' THEN 1 WHEN 'direct-unavailable' THEN 0 ELSE .5 END,CASE r.provenance WHEN 'direct' THEN .99 WHEN 'direct-unavailable' THEN .95 ELSE .25 END,'TMDB status: '||r.provenance,@now FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id LEFT JOIN tmdb_entity e ON e.entity_type='person' AND e.tmdb_id=r.resolved_tmdb_id WHERE p.item_type='person'
UNION ALL SELECT @run,p.emby_id,'emby:'||p.emby_id,'tvdb',CASE r.provenance WHEN 'direct' THEN 'identity-live' WHEN 'direct-unavailable' THEN 'identity-unavailable' ELSE 'identity-unresolved' END,p.tvdb_id,r.resolved_tvdb_id,p.name,e.name,CASE r.provenance WHEN 'direct' THEN 1 WHEN 'direct-unavailable' THEN 0 ELSE .5 END,CASE r.provenance WHEN 'direct' THEN .99 WHEN 'direct-unavailable' THEN .95 ELSE .25 END,'TVDB status: '||r.provenance,@now FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id LEFT JOIN tvdb_entity e ON e.entity_type='person' AND e.tvdb_id=r.resolved_tvdb_id WHERE p.item_type='person'",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void MissingIdentitySignals(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,score,confidence,evidence_text,created_utc)
SELECT @run,p.emby_id,'emby:'||p.emby_id,'tmdb',CASE WHEN p.tmdb_id IS NULL THEN 'identity-missing' ELSE 'identity-unresolved' END,p.tmdb_id,p.name,0,.2,CASE WHEN p.tmdb_id IS NULL THEN 'No TMDB person ID is assigned' ELSE 'No TMDB resolution observation is archived' END,@now FROM emby_item p LEFT JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.emby_id IS NULL
UNION ALL SELECT @run,p.emby_id,'emby:'||p.emby_id,'tvdb',CASE WHEN p.tvdb_id IS NULL THEN 'identity-missing' ELSE 'identity-unresolved' END,p.tvdb_id,p.name,0,.2,CASE WHEN p.tvdb_id IS NULL THEN 'No TVDB person ID is assigned' ELSE 'No TVDB resolution observation is archived' END,@now FROM emby_item p LEFT JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.emby_id IS NULL",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void UniversalIdentityAudits(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH media AS (
SELECT p.emby_id person_id,p.name current_name,p.tmdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(m.tmdb_id,mr.resolved_tmdb_id) production_id,coalesce(json_extract(me.raw_json,'$.show_id'),parent.tmdb_id,pr.resolved_tmdb_id) series_id,me.tmdb_id checked_id,exact.person_tmdb_id exact_person,broad.person_tmdb_id broad_person
FROM emby_item p LEFT JOIN emby_relationship er ON er.person_emby_id=p.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_entity me ON me.tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND me.entity_type=m.item_type LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN tmdb_item_resolution pr ON pr.emby_id=parent.emby_id LEFT JOIN tmdb_credit exact ON exact.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND exact.production_type=m.item_type AND exact.person_tmdb_id=p.tmdb_id LEFT JOIN tmdb_credit broad ON m.item_type='episode' AND broad.production_tmdb_id=coalesce(json_extract(me.raw_json,'$.show_id'),parent.tmdb_id,pr.resolved_tmdb_id) AND broad.production_type='series' AND broad.person_tmdb_id=p.tmdb_id WHERE p.item_type='person'), classified AS (
SELECT media.*,CASE WHEN media_emby_id IS NULL THEN 'no-media' WHEN production_id IS NULL THEN 'unresolved' WHEN exact_person IS NOT NULL THEN 'exact' WHEN media_type='episode' AND broad_person IS NOT NULL THEN 'broader' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM tmdb_fetch_cache f WHERE f.cache_key='episode-credits:'||production_id AND f.state='success') THEN 'not-present' WHEN media_type<>'episode' AND checked_id IS NOT NULL THEN 'not-present' ELSE 'unchecked' END result FROM media), audit AS (
SELECT person_id,current_name,current_id,count(DISTINCT media_emby_id) linked,count(DISTINCT CASE WHEN result IN('exact','broader','not-present') THEN media_emby_id END) checked,count(DISTINCT CASE WHEN result='exact' THEN media_emby_id END) exact_count,count(DISTINCT CASE WHEN result='broader' THEN media_emby_id END) broader_count,count(DISTINCT CASE WHEN result='not-present' THEN media_emby_id END) not_present,count(DISTINCT CASE WHEN result IN('unresolved','unchecked') THEN media_emby_id END) unresolved FROM classified GROUP BY person_id,current_name,current_id)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,evidence_json,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tmdb',CASE WHEN current_id IS NULL THEN 'identity-audit-missing' WHEN linked=0 THEN 'identity-audit-unlinked' WHEN exact_count+broader_count>0 AND not_present=0 THEN 'identity-supported' WHEN exact_count+broader_count>0 THEN 'identity-partially-supported' WHEN checked=0 THEN 'identity-audit-incomplete' ELSE 'identity-unsupported' END,current_id,current_name,linked,checked,exact_count+broader_count,CASE WHEN linked=0 THEN NULL ELSE (exact_count+.9*broader_count)/linked END,CASE WHEN linked=0 THEN .25 WHEN exact_count+broader_count>0 AND not_present=0 THEN .95 WHEN exact_count+broader_count>0 THEN .65 WHEN checked=linked THEN .2 ELSE .3 END,'TMDB identity audit: linked='||linked||'; checked='||checked||'; exact='||exact_count||'; broader-series='||broader_count||'; not-present='||not_present||'; unresolved='||unresolved,json_object('linked',linked,'checked',checked,'exact_scope',exact_count,'broader_series_scope',broader_count,'not_present',not_present,'unresolved',unresolved),@now FROM audit",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"WITH episode_series AS (SELECT DISTINCT production_tvdb_id,source_tvdb_id FROM tvdb_credit_observation WHERE production_type='episode' AND source_entity_type='series'), media AS (
SELECT p.emby_id person_id,p.name current_name,p.tvdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(m.tvdb_id,mr.resolved_tvdb_id) production_id,coalesce(parent.tvdb_id,pr.resolved_tvdb_id,series_credit.source_tvdb_id) series_id,me.tvdb_id checked_id,exact.person_tvdb_id exact_person,broad.person_tvdb_id broad_person
FROM emby_item p LEFT JOIN emby_relationship er ON er.person_emby_id=p.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tvdb_entity me ON me.tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND me.entity_type=m.item_type LEFT JOIN episode_series series_credit ON m.item_type='episode' AND series_credit.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN item_resolution pr ON pr.emby_id=parent.emby_id LEFT JOIN credit exact ON exact.subject_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND exact.subject_type=m.item_type AND exact.person_tvdb_id=p.tvdb_id LEFT JOIN credit broad ON m.item_type='episode' AND broad.subject_tvdb_id=coalesce(parent.tvdb_id,pr.resolved_tvdb_id,series_credit.source_tvdb_id) AND broad.subject_type='series' AND broad.person_tvdb_id=p.tvdb_id WHERE p.item_type='person'), classified AS (
SELECT media.*,CASE WHEN media_emby_id IS NULL THEN 'no-media' WHEN production_id IS NULL THEN 'unresolved' WHEN exact_person IS NOT NULL THEN 'exact' WHEN media_type='episode' AND broad_person IS NOT NULL THEN 'broader' WHEN checked_id IS NOT NULL THEN 'not-present' ELSE 'unchecked' END result FROM media), audit AS (
SELECT person_id,current_name,current_id,count(DISTINCT media_emby_id) linked,count(DISTINCT CASE WHEN result IN('exact','broader','not-present') THEN media_emby_id END) checked,count(DISTINCT CASE WHEN result='exact' THEN media_emby_id END) exact_count,count(DISTINCT CASE WHEN result='broader' THEN media_emby_id END) broader_count,count(DISTINCT CASE WHEN result='not-present' THEN media_emby_id END) not_present,count(DISTINCT CASE WHEN result IN('unresolved','unchecked') THEN media_emby_id END) unresolved FROM classified GROUP BY person_id,current_name,current_id)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,evidence_json,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tvdb',CASE WHEN current_id IS NULL THEN 'identity-audit-missing' WHEN linked=0 THEN 'identity-audit-unlinked' WHEN exact_count+broader_count>0 AND not_present=0 THEN 'identity-supported' WHEN exact_count+broader_count>0 THEN 'identity-partially-supported' WHEN checked=0 THEN 'identity-audit-incomplete' ELSE 'identity-unsupported' END,current_id,current_name,linked,checked,exact_count+broader_count,CASE WHEN linked=0 THEN NULL ELSE (exact_count+.9*broader_count)/linked END,CASE WHEN linked=0 THEN .25 WHEN exact_count+broader_count>0 AND not_present=0 THEN .95 WHEN exact_count+broader_count>0 THEN .65 WHEN checked=linked THEN .2 ELSE .3 END,'TVDB identity audit: linked='||linked||'; checked='||checked||'; exact='||exact_count||'; broader-series='||broader_count||'; not-present='||not_present||'; unresolved='||unresolved,json_object('linked',linked,'checked',checked,'exact_scope',exact_count,'broader_series_scope',broader_count,'not_present',not_present,'unresolved',unresolved),@now FROM audit",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
        }

        private static void RelationshipSignals(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH media AS (
SELECT p.emby_id person_id,p.name current_name,p.tmdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(nullif(er.role,''),er.person_type) relationship_role,coalesce(m.tmdb_id,mr.resolved_tmdb_id) production_id,coalesce(parent.tmdb_id,pr.resolved_tmdb_id,json_extract(me.raw_json,'$.show_id')) series_id,m.name media_name
FROM emby_item p JOIN tmdb_item_resolution dead ON dead.emby_id=p.emby_id AND dead.provenance='direct-unavailable' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_entity me ON me.tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND me.entity_type=m.item_type LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN tmdb_item_resolution pr ON pr.emby_id=parent.emby_id WHERE p.item_type='person')
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,media_emby_id,media_type,relationship_role,checked_media_count,evidence_text,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tmdb',CASE WHEN production_id IS NULL THEN 'media-unavailable' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM tmdb_fetch_cache f WHERE f.cache_key='episode-credits:'||production_id AND f.state='success') THEN 'media-checked' WHEN media_type<>'episode' AND EXISTS(SELECT 1 FROM tmdb_entity e WHERE e.tmdb_id=media.production_id AND e.entity_type=media.media_type) THEN 'media-checked' ELSE 'unchecked' END,current_id,current_name,media_emby_id,media_type,relationship_role,CASE WHEN production_id IS NOT NULL AND (media_type='episode' AND EXISTS(SELECT 1 FROM tmdb_fetch_cache f WHERE f.cache_key='episode-credits:'||production_id AND f.state='success') OR media_type<>'episode' AND EXISTS(SELECT 1 FROM tmdb_entity e WHERE e.tmdb_id=media.production_id AND e.entity_type=media.media_type)) THEN 1 ELSE 0 END,'TMDB media '||media_emby_id||' '||coalesce(media_name,'')||'; provider production='||coalesce(production_id,'unresolved'),@now FROM media",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"WITH media AS (
SELECT p.emby_id person_id,p.name current_name,p.tvdb_id current_id,er.media_emby_id,m.item_type media_type,coalesce(nullif(er.role,''),er.person_type) relationship_role,coalesce(m.tvdb_id,mr.resolved_tvdb_id) production_id,coalesce(parent.tvdb_id,pr.resolved_tvdb_id,(SELECT c.source_tvdb_id FROM tvdb_credit_observation c WHERE c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type='episode' AND c.source_entity_type='series' LIMIT 1)) series_id,m.name media_name
FROM emby_item p JOIN item_resolution dead ON dead.emby_id=p.emby_id AND dead.provenance='direct-unavailable' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN item_resolution pr ON pr.emby_id=parent.emby_id WHERE p.item_type='person')
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,current_name,media_emby_id,media_type,relationship_role,checked_media_count,evidence_text,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tvdb',CASE WHEN production_id IS NULL THEN 'media-unavailable' WHEN EXISTS(SELECT 1 FROM tvdb_entity e WHERE e.tvdb_id=media.production_id AND e.entity_type=media.media_type) THEN 'media-checked' ELSE 'unchecked' END,current_id,current_name,media_emby_id,media_type,relationship_role,CASE WHEN production_id IS NOT NULL AND EXISTS(SELECT 1 FROM tvdb_entity e WHERE e.tvdb_id=media.production_id AND e.entity_type=media.media_type) THEN 1 ELSE 0 END,'TVDB media '||media_emby_id||' '||coalesce(media_name,'')||'; provider production='||coalesce(production_id,'unresolved'),@now FROM media",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"WITH candidates AS (SELECT rc.emby_id,rc.tmdb_id candidate_id,rc.name candidate_name FROM tmdb_resolution_candidate rc), media AS (
SELECT p.emby_id person_id,p.name current_name,p.tmdb_id current_id,c.candidate_id,c.candidate_name,er.media_emby_id,m.item_type media_type,coalesce(nullif(er.role,''),er.person_type) relationship_role,coalesce(m.tmdb_id,mr.resolved_tmdb_id) production_id,coalesce(parent.tmdb_id,pr.resolved_tmdb_id,json_extract(me.raw_json,'$.show_id')) series_id,m.name media_name
FROM emby_item p JOIN candidates c ON c.emby_id=p.emby_id JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_entity me ON me.tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND me.entity_type=m.item_type LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN tmdb_item_resolution pr ON pr.emby_id=parent.emby_id), classified AS (
SELECT media.*,CASE WHEN production_id IS NULL THEN 'media-unavailable' WHEN EXISTS(SELECT 1 FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tmdb_id=media.candidate_id) THEN 'confirmed-exact-scope' WHEN media_type='episode' AND series_id IS NOT NULL AND EXISTS(SELECT 1 FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.series_id AND c.production_type='series' AND c.person_tmdb_id=media.candidate_id) THEN 'confirmed-broader-series-scope' WHEN media_type='episode' AND EXISTS(SELECT 1 FROM tmdb_fetch_cache f WHERE f.cache_key='episode-credits:'||production_id AND f.state='success') THEN 'not-present' WHEN media_type<>'episode' AND EXISTS(SELECT 1 FROM tmdb_entity e WHERE e.tmdb_id=media.production_id AND e.entity_type=media.media_type) THEN 'not-present' ELSE 'unchecked' END result,
coalesce((SELECT c.job_or_character FROM tmdb_credit_observation c WHERE c.production_tmdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tmdb_id=media.candidate_id LIMIT 1),(SELECT c.job_or_character FROM tmdb_credit_observation c WHERE media.media_type='episode' AND c.production_tmdb_id=media.series_id AND c.production_type='series' AND c.person_tmdb_id=media.candidate_id LIMIT 1)) provider_role FROM media)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,candidate_external_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tmdb',result,current_id,candidate_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,1,CASE WHEN result IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN 1 ELSE 0 END,CASE WHEN result LIKE 'confirmed-%' THEN 1 ELSE 0 END,CASE result WHEN 'confirmed-exact-scope' THEN 1 WHEN 'confirmed-broader-series-scope' THEN .9 WHEN 'not-present' THEN 0 ELSE NULL END,CASE result WHEN 'confirmed-exact-scope' THEN .95 WHEN 'confirmed-broader-series-scope' THEN .85 WHEN 'not-present' THEN .8 ELSE .2 END,'TMDB candidate '||candidate_id||' '||coalesce(candidate_name,'')||' on Emby media '||media_emby_id||' '||coalesce(media_name,'')||': '||result||'; Emby role='||coalesce(relationship_role,'-')||'; provider role='||coalesce(provider_role,'-'),@now FROM classified",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,@"WITH candidates AS (SELECT rc.emby_id,rc.tvdb_id candidate_id,rc.name candidate_name FROM resolution_candidate rc WHERE rc.entity_type='person'), media AS (
SELECT p.emby_id person_id,p.name current_name,p.tvdb_id current_id,c.candidate_id,c.candidate_name,er.media_emby_id,m.item_type media_type,coalesce(nullif(er.role,''),er.person_type) relationship_role,coalesce(m.tvdb_id,mr.resolved_tvdb_id) production_id,coalesce(parent.tvdb_id,pr.resolved_tvdb_id,(SELECT tc.source_tvdb_id FROM tvdb_credit_observation tc WHERE tc.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND tc.production_type='episode' AND tc.source_entity_type='series' LIMIT 1)) series_id,m.name media_name
FROM emby_item p JOIN candidates c ON c.emby_id=p.emby_id JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN emby_item parent ON parent.emby_id=m.parent_emby_id LEFT JOIN item_resolution pr ON pr.emby_id=parent.emby_id), classified AS (
SELECT media.*,CASE WHEN production_id IS NULL THEN 'media-unavailable' WHEN EXISTS(SELECT 1 FROM tvdb_credit_observation c WHERE c.production_tvdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tvdb_id=media.candidate_id) THEN 'confirmed-exact-scope' WHEN media_type='episode' AND series_id IS NOT NULL AND EXISTS(SELECT 1 FROM tvdb_credit_observation c WHERE c.production_tvdb_id=media.series_id AND c.production_type='series' AND c.person_tvdb_id=media.candidate_id) THEN 'confirmed-broader-series-scope' WHEN EXISTS(SELECT 1 FROM tvdb_entity e WHERE e.tvdb_id=media.production_id AND e.entity_type=media.media_type) THEN 'not-present' ELSE 'unchecked' END result,
coalesce((SELECT c.role_name FROM tvdb_credit_observation c WHERE c.production_tvdb_id=media.production_id AND c.production_type=media.media_type AND c.person_tvdb_id=media.candidate_id LIMIT 1),(SELECT c.role_name FROM tvdb_credit_observation c WHERE media.media_type='episode' AND c.production_tvdb_id=media.series_id AND c.production_type='series' AND c.person_tvdb_id=media.candidate_id LIMIT 1)) provider_role FROM media)
INSERT INTO housekeeping_signal(run_id,person_emby_id,subject_truth_entity_id,provider,signal_type,current_external_id,candidate_external_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,linked_media_count,checked_media_count,supported_media_count,score,confidence,evidence_text,created_utc)
SELECT @run,person_id,'emby:'||person_id,'tvdb',result,current_id,candidate_id,current_name,candidate_name,media_emby_id,media_type,relationship_role,provider_role,1,CASE WHEN result IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN 1 ELSE 0 END,CASE WHEN result LIKE 'confirmed-%' THEN 1 ELSE 0 END,CASE result WHEN 'confirmed-exact-scope' THEN 1 WHEN 'confirmed-broader-series-scope' THEN .9 WHEN 'not-present' THEN 0 ELSE NULL END,CASE result WHEN 'confirmed-exact-scope' THEN .95 WHEN 'confirmed-broader-series-scope' THEN .85 WHEN 'not-present' THEN .8 ELSE .2 END,'TVDB candidate '||candidate_id||' '||coalesce(candidate_name,'')||' on Emby media '||media_emby_id||' '||coalesce(media_name,'')||': '||result||'; Emby role='||coalesce(relationship_role,'-')||'; provider role='||coalesce(provider_role,'-'),@now FROM classified",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
