        private static void CandidateDecisions(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH stats AS (
SELECT person_emby_id,provider,current_external_id,candidate_external_id,max(current_name) current_name,max(candidate_name) candidate_name,count(DISTINCT media_emby_id) linked,sum(CASE WHEN signal_type IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN 1 ELSE 0 END) checked,sum(CASE WHEN signal_type LIKE 'confirmed-%' THEN 1 ELSE 0 END) supported,sum(CASE signal_type WHEN 'confirmed-exact-scope' THEN 1.0 WHEN 'confirmed-broader-series-scope' THEN .9 ELSE 0 END) weighted
FROM housekeeping_signal WHERE run_id=@run AND candidate_external_id IS NOT NULL AND media_emby_id IS NOT NULL GROUP BY person_emby_id,provider,current_external_id,candidate_external_id), owners AS (
SELECT 'tmdb' provider,tmdb_id external_id,emby_id,name FROM emby_item WHERE item_type='person' AND tmdb_id IS NOT NULL UNION ALL SELECT 'tvdb',tvdb_id,emby_id,name FROM emby_item WHERE item_type='person' AND tvdb_id IS NOT NULL), owned AS (
SELECT s.*,o.emby_id owner_emby_id,o.name owner_name FROM stats s JOIN owners o ON o.provider=s.provider AND o.external_id=s.candidate_external_id AND o.emby_id<>s.person_emby_id WHERE s.supported>0 AND s.candidate_external_id<>coalesce(s.current_external_id,''))
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,person_emby_id,'emby:'||person_emby_id,'merge','review-merge','candidate-owned-by-emby',provider,CASE WHEN person_emby_id<owner_emby_id THEN person_emby_id||','||owner_emby_id ELSE owner_emby_id||','||person_emby_id END,candidate_external_id,linked,checked,supported,min(.97,.72+.18*weighted/max(1,linked)),'Candidate '||upper(provider)||' ID '||candidate_external_id||' ('||coalesce(candidate_name,'')||') is directly supported on '||supported||' linked media for Emby '||person_emby_id||' and is already assigned to Emby '||owner_emby_id||' ('||coalesce(owner_name,'')||'). Review relationship reassignment and choose a survivor; do not remove the unavailable ID in isolation.',@now FROM owned
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.recommendation_type='review-merge' AND h.provider=owned.provider AND ((h.current_value=owned.person_emby_id||','||owned.owner_emby_id) OR (h.current_value=owned.owner_emby_id||','||owned.person_emby_id)))",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
            Exec(x,"DELETE FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='replace-provider-id' AND EXISTS(SELECT 1 FROM housekeeping_recommendation m WHERE m.run_id=@run AND m.recommendation_type='review-merge' AND m.provider=housekeeping_recommendation.provider AND m.proposed_value=housekeeping_recommendation.proposed_value AND (','||m.current_value||',') LIKE '%,'||housekeeping_recommendation.person_emby_id||',%')",s=>s.TryBind("@run",run));
            Exec(x,@"WITH positives AS (
SELECT s.person_emby_id,s.provider,s.current_external_id,s.candidate_external_id,count(DISTINCT s.media_emby_id) linked,count(DISTINCT CASE WHEN s.signal_type IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN s.media_emby_id END) checked,count(DISTINCT CASE WHEN s.signal_type LIKE 'confirmed-%' THEN s.media_emby_id END) supported FROM housekeeping_signal s WHERE s.run_id=@run AND s.candidate_external_id IS NOT NULL AND s.candidate_external_id<>coalesce(s.current_external_id,'') GROUP BY s.person_emby_id,s.provider,s.current_external_id,s.candidate_external_id), grouped AS (
SELECT person_emby_id,provider,current_external_id,group_concat(candidate_external_id) candidate_ids,max(linked) linked,max(checked) checked,sum(supported) supported FROM positives WHERE supported>0 GROUP BY person_emby_id,provider,current_external_id)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,g.person_emby_id,'emby:'||g.person_emby_id,'change_identity','review-unresolved-provider-id','partial-alternative-support',g.provider,g.current_external_id,g.candidate_ids,g.linked,g.checked,g.supported,.62,upper(g.provider)||' found positive media evidence for alternative ID(s) '||g.candidate_ids||' on '||g.supported||' relationship(s), below a decisive replacement or partition threshold. Review the retained candidate evidence.',@now
FROM grouped g WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=g.person_emby_id AND h.provider=g.provider AND h.recommendation_type IN('replace-provider-id','review-merge'))",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
        }

        private static void UniversalAuditDecisions(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,s.person_emby_id,s.subject_truth_entity_id,'change_identity','review-unresolved-provider-id',CASE s.signal_type WHEN 'identity-unsupported' THEN 'current-identity-not-on-media' WHEN 'identity-partially-supported' THEN 'current-identity-partial-media-conflict' WHEN 'identity-audit-missing' THEN 'missing-provider-identity' ELSE 'incomplete-media-coverage' END,s.provider,s.current_external_id,coalesce(s.linked_media_count,0),coalesce(s.checked_media_count,0),coalesce(s.supported_media_count,0),CASE s.signal_type WHEN 'identity-unsupported' THEN .30 WHEN 'identity-partially-supported' THEN .55 ELSE .35 END,s.evidence_text||'. The universal audit found insufficient or contradictory evidence; inspect retained candidates and relationship observations before changing the identity.',@now
FROM housekeeping_signal s WHERE s.run_id=@run AND s.signal_type IN('identity-unsupported','identity-partially-supported','identity-audit-missing','identity-audit-incomplete') AND coalesce(s.linked_media_count,0)>0 AND NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=s.person_emby_id AND h.provider=s.provider AND h.recommendation_type IN('replace-provider-id','review-merge','review-unresolved-provider-id'))",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void ProviderIssues(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH candidate_rows AS (
SELECT DISTINCT s.person_emby_id,s.provider,s.candidate_external_id id,s.candidate_name name,e.birth_date birth,CASE WHEN s.signal_type LIKE 'confirmed-%' OR p.tmdb_id=s.candidate_external_id THEN 1 ELSE 0 END anchored FROM housekeeping_signal s JOIN tmdb_entity e ON s.provider='tmdb' AND e.entity_type='person' AND e.tmdb_id=s.candidate_external_id JOIN emby_item p ON p.emby_id=s.person_emby_id WHERE s.run_id=@run AND s.candidate_external_id IS NOT NULL
UNION ALL SELECT DISTINCT s.person_emby_id,s.provider,s.candidate_external_id,s.candidate_name,e.birth_date,CASE WHEN s.signal_type LIKE 'confirmed-%' OR p.tvdb_id=s.candidate_external_id THEN 1 ELSE 0 END FROM housekeeping_signal s JOIN tvdb_entity e ON s.provider='tvdb' AND e.entity_type='person' AND e.tvdb_id=s.candidate_external_id JOIN emby_item p ON p.emby_id=s.person_emby_id WHERE s.run_id=@run AND s.candidate_external_id IS NOT NULL), candidate_people AS (
SELECT person_emby_id,provider,id,max(name) name,max(birth) birth,max(anchored) anchored FROM candidate_rows GROUP BY person_emby_id,provider,id), pairs AS (
SELECT a.person_emby_id,a.provider,CASE WHEN cast(a.id AS integer)<cast(b.id AS integer) THEN a.id||','||b.id ELSE b.id||','||a.id END ids,a.id id1,b.id id2,a.name name1,b.name name2,a.birth birth1,b.birth birth2,max(a.anchored,b.anchored) anchored
FROM candidate_people a JOIN candidate_people b ON b.person_emby_id=a.person_emby_id AND b.provider=a.provider AND b.id>a.id WHERE a.birth IS NOT NULL AND a.birth<>'' AND a.birth=b.birth AND (lower(replace(a.name,'.',''))=lower(replace(b.name,'.','')) OR lower(substr(a.name,1,instr(a.name||' ',' ')-1))=lower(substr(b.name,1,instr(b.name||' ',' ')-1))))
INSERT INTO provider_identity_issue(provider,issue_type,identity_ids,related_emby_ids,status,confidence,evidence_json,first_observed_utc,last_observed_utc)
SELECT provider,'person-split',ids,cast(person_emby_id AS text),'pending',.78,json_object('identity_1',id1,'name_1',name1,'identity_2',id2,'name_2',name2,'shared_birth_date',birth1,'reason','Compatible names and identical birth dates nominate a provider-side person split; linked-media evidence remains separately reviewable.'),@now,@now FROM pairs
WHERE anchored=1
AND (provider<>'tvdb' OR 2>(SELECT count(DISTINCT ra.source_name) FROM remote_id ra JOIN remote_id rb ON rb.entity_type='person' AND rb.tvdb_id=id2 AND rb.source_name=ra.source_name AND rb.remote_id<>ra.remote_id WHERE ra.entity_type='person' AND ra.tvdb_id=id1 AND ra.source_name IN('IMDB','TheMovieDB.com')))
AND (provider<>'tmdb' OR 2>(SELECT count(DISTINCT xa.source_name) FROM tmdb_external_id xa JOIN tmdb_external_id xb ON xb.entity_type='person' AND xb.tmdb_id=id2 AND xb.source_name=xa.source_name AND xb.external_id<>xa.external_id WHERE xa.entity_type='person' AND xa.tmdb_id=id1 AND xa.source_name IN('imdb','tvdb','wikidata')))
ON CONFLICT(provider,issue_type,identity_ids) DO UPDATE SET related_emby_ids=excluded.related_emby_ids,last_observed_utc=excluded.last_observed_utc,evidence_json=excluded.evidence_json,confidence=excluded.confidence",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});
        }

        private void Reacquire(string provider,long run,CancellationToken token,Action<string,double,TimeSpan> report,Stopwatch clock,double start,double endPercent)
        {
            long total=CountCandidates(provider),last=0,done=0;
            while(true){token.ThrowIfCancellationRequested();long end=NextEnd(provider,last);if(end==0)break;long batch=0;
                Tx(x=>{ReacquiredBatch(x,provider,run,last,end);batch=CountRange(x,provider,last,end);done+=batch;State(x,run,provider+"-reacquisition",start+(endPercent-start)*done/Math.Max(1d,total));});
                last=end;report?.Invoke(provider.ToUpperInvariant()+" reacquisition "+done+"/"+total,start+(endPercent-start)*done/Math.Max(1d,total),clock.Elapsed);}
        }

        private long CountCandidates(string p)=>Scalar(p=="tmdb"?"SELECT count(*) FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.provenance='inferred' AND r.resolved_tmdb_id IS NOT NULL AND coalesce(p.tmdb_id,'')<>r.resolved_tmdb_id":"SELECT count(*) FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.provenance='inferred' AND r.resolved_tvdb_id IS NOT NULL AND coalesce(p.tvdb_id,'')<>r.resolved_tvdb_id");
        private long NextEnd(string p,long last)=>Scalar(db,p=="tmdb"?"SELECT max(emby_id) FROM (SELECT p.emby_id FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.item_type='person' AND r.provenance='inferred' AND r.resolved_tmdb_id IS NOT NULL AND coalesce(p.tmdb_id,'')<>r.resolved_tmdb_id ORDER BY p.emby_id LIMIT 1000)":"SELECT max(emby_id) FROM (SELECT p.emby_id FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.item_type='person' AND r.provenance='inferred' AND r.resolved_tvdb_id IS NOT NULL AND coalesce(p.tvdb_id,'')<>r.resolved_tvdb_id ORDER BY p.emby_id LIMIT 1000)",s=>s.TryBind("@last",last));
        private static long CountRange(IDatabaseConnection x,string p,long last,long end)=>Scalar(x,p=="tmdb"?"SELECT count(*) FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.emby_id<=@end AND p.item_type='person' AND r.provenance='inferred' AND r.resolved_tmdb_id IS NOT NULL AND coalesce(p.tmdb_id,'')<>r.resolved_tmdb_id":"SELECT count(*) FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.emby_id<=@end AND p.item_type='person' AND r.provenance='inferred' AND r.resolved_tvdb_id IS NOT NULL AND coalesce(p.tvdb_id,'')<>r.resolved_tvdb_id",s=>{s.TryBind("@last",last);s.TryBind("@end",end);});

        private static void ReacquiredBatch(IDatabaseConnection x,string p,long run,long last,long end)
        {
            var sql=p=="tmdb"?@"WITH q AS (SELECT p.emby_id,p.tmdb_id old_id,r.resolved_tmdb_id new_id,r.evidence_json FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.emby_id<=@end AND p.item_type='person' AND r.resolved_tmdb_id IS NOT NULL AND coalesce(p.tmdb_id,'')<>r.resolved_tmdb_id),v AS (SELECT q.emby_id,count(DISTINCT er.media_emby_id) linked,count(DISTINCT CASE WHEN c.person_tmdb_id=q.new_id THEN er.media_emby_id END) supported FROM q LEFT JOIN emby_relationship er ON er.person_emby_id=q.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=q.new_id GROUP BY q.emby_id) INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc) SELECT @run,q.emby_id,'emby:'||q.emby_id,'change_identity','replace-provider-id','linked-media-identity','tmdb',q.old_id,q.new_id,v.linked,v.linked,v.supported,.90,coalesce(q.evidence_json,'TMDB replacement'),@now FROM q JOIN v ON v.emby_id=q.emby_id":@"WITH q AS (SELECT p.emby_id,p.tvdb_id old_id,r.resolved_tvdb_id new_id,r.evidence_json FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.emby_id>@last AND p.emby_id<=@end AND p.item_type='person' AND r.resolved_tvdb_id IS NOT NULL AND coalesce(p.tvdb_id,'')<>r.resolved_tvdb_id),v AS (SELECT q.emby_id,count(DISTINCT er.media_emby_id) linked,count(DISTINCT CASE WHEN c.person_tvdb_id=q.new_id THEN er.media_emby_id END) supported FROM q LEFT JOIN emby_relationship er ON er.person_emby_id=q.emby_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tvdb_credit_observation c ON c.production_tvdb_id=m.tvdb_id AND c.person_tvdb_id=q.new_id GROUP BY q.emby_id) INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc) SELECT @run,q.emby_id,'emby:'||q.emby_id,'change_identity','replace-provider-id','linked-media-identity','tvdb',q.old_id,q.new_id,v.linked,v.linked,v.supported,.88,coalesce(q.evidence_json,'TVDB replacement'),@now FROM q JOIN v ON v.emby_id=q.emby_id";
            if(p=="tmdb") sql=sql.Replace("r.evidence_json FROM","r.evidence_json,r.method FROM")
                .Replace("LEFT JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id","LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id LEFT JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id)")
                .Replace("v.linked,v.linked,v.supported,.90,coalesce","v.linked,CASE WHEN q.method='targeted-scope-aware-media-cast' THEN coalesce(json_extract(q.evidence_json,'$.checked_exact_scope_media'),v.linked) ELSE v.linked END,CASE WHEN q.method='targeted-scope-aware-media-cast' THEN coalesce(json_extract(q.evidence_json,'$.exact_scope_cast_matches'),0)+coalesce(json_extract(q.evidence_json,'$.broader_series_scope_episode_matches'),0) ELSE v.supported END,CASE WHEN q.method='targeted-scope-aware-media-cast' THEN coalesce(json_extract(q.evidence_json,'$.confidence'),.90) ELSE .90 END,coalesce");
            else sql=sql.Replace("r.evidence_json FROM","r.evidence_json,r.confidence resolution_confidence,r.method FROM")
                .Replace("v.supported,.88,coalesce","CASE WHEN q.method='targeted-scope-aware-media-cast' THEN coalesce(json_extract(q.evidence_json,'$.exact_scope_cast_matches'),0)+coalesce(json_extract(q.evidence_json,'$.broader_series_scope_episode_matches'),0) ELSE v.supported END,coalesce(q.resolution_confidence,.88),coalesce");
            sql=sql.Replace("WHERE p.emby_id>@last","WHERE r.provenance='inferred' AND p.emby_id>@last")
                .Replace("FROM q JOIN v ON v.emby_id=q.emby_id",p=="tmdb"?"FROM q JOIN v ON v.emby_id=q.emby_id JOIN tmdb_item_resolution rr ON rr.emby_id=q.emby_id WHERE v.supported>0 OR rr.method='targeted-scope-aware-media-cast'":"FROM q JOIN v ON v.emby_id=q.emby_id WHERE v.supported>0 OR q.method='targeted-scope-aware-media-cast'");
            Exec(x,sql,s=>{s.TryBind("@run",run);s.TryBind("@last",last);s.TryBind("@end",end);s.TryBind("@now",Now());});
        }

        private static void Unavailable(IDatabaseConnection x,long run)=>Exec(x,@"INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,linked_media_count,confidence,evidence_summary,created_utc) SELECT @run,p.emby_id,'emby:'||p.emby_id,'change_identity','remove-provider-id','identity-unavailable','tmdb',p.tmdb_id,(SELECT count(*) FROM emby_relationship e WHERE e.person_emby_id=p.emby_id),.80,'TMDB explicitly reports identity unavailable',@now FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.provenance='direct-unavailable' AND r.resolved_tmdb_id IS NULL UNION ALL SELECT @run,p.emby_id,'emby:'||p.emby_id,'change_identity','remove-provider-id','identity-unavailable','tvdb',p.tvdb_id,(SELECT count(*) FROM emby_relationship e WHERE e.person_emby_id=p.emby_id),.80,'TVDB explicitly reports identity unavailable',@now FROM emby_item p JOIN item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.provenance='direct-unavailable' AND r.resolved_tvdb_id IS NULL",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void UnavailableExplicit(IDatabaseConnection x,long run)=>Exec(x,@"WITH coverage AS (
