INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,c.person_emby_id,'emby:'||c.person_emby_id,'change_identity','remove-provider-id','identity-unavailable',c.provider,CASE c.provider WHEN 'tmdb' THEN p.tmdb_id ELSE p.tvdb_id END,c.linked,c.checked,0,.80,upper(c.provider)||' explicitly reports the assigned identity unavailable. All '||c.checked||' of '||c.linked||' linked media were resolved and checked; no compatible candidate was present. Candidate and relationship signals are retained for review.',@now
FROM coverage c JOIN emby_item p ON p.emby_id=c.person_emby_id LEFT JOIN positives q ON q.person_emby_id=c.person_emby_id AND q.provider=c.provider WHERE c.linked=c.checked AND coalesce(q.supported,0)=0 AND NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=c.person_emby_id AND h.provider=c.provider AND h.recommendation_type IN('replace-provider-id','review-merge','review-unresolved-provider-id'))",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void MediaBackedTmdbReplacements(IDatabaseConnection x,long run)=>Exec(x,@"WITH dead AS (
SELECT p.emby_id,p.name,p.tmdb_id,(SELECT count(*) FROM emby_relationship er WHERE er.person_emby_id=p.emby_id) linked,
 (SELECT count(DISTINCT er.media_emby_id) FROM emby_relationship er JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id WHERE er.person_emby_id=p.emby_id AND coalesce(m.tmdb_id,mr.resolved_tmdb_id) IS NOT NULL) checked
FROM emby_item p JOIN tmdb_item_resolution r ON r.emby_id=p.emby_id WHERE p.item_type='person' AND r.provenance='direct-unavailable'), candidates AS (
SELECT d.emby_id,d.name current_name,d.tmdb_id old_id,d.linked,d.checked,e.tmdb_id new_id,e.name candidate_name,count(DISTINCT er.media_emby_id) supported,
 CASE WHEN lower(e.name)=lower(d.name) OR EXISTS(SELECT 1 FROM tmdb_alias a WHERE a.entity_type='person' AND a.tmdb_id=e.tmdb_id AND lower(a.alias)=lower(d.name)) THEN 1 ELSE 0 END exact_or_alias
FROM dead d JOIN emby_relationship er ON er.person_emby_id=d.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) JOIN tmdb_entity e ON e.entity_type='person' AND e.tmdb_id=c.person_tmdb_id
WHERE e.tmdb_id<>d.tmdb_id AND (lower(e.name)=lower(d.name) OR EXISTS(SELECT 1 FROM tmdb_alias a WHERE a.entity_type='person' AND a.tmdb_id=e.tmdb_id AND lower(a.alias)=lower(d.name)) OR (substr(lower(e.name),1,1)=substr(lower(d.name),1,1) AND instr(e.name,' ')>0 AND instr(d.name,' ')>0 AND lower(substr(e.name,instr(e.name,' ')+1))=lower(substr(d.name,instr(d.name,' ')+1))))
GROUP BY d.emby_id,d.name,d.tmdb_id,d.linked,d.checked,e.tmdb_id,e.name), eligible AS (
SELECT c.* FROM candidates c WHERE (c.exact_or_alias=1 AND c.supported>0) OR (c.exact_or_alias=0 AND c.checked>=2 AND c.supported=c.checked)), winners AS (
SELECT e.* FROM eligible e WHERE e.supported=(SELECT max(x.supported) FROM eligible x WHERE x.emby_id=e.emby_id) AND 1=(SELECT count(*) FROM eligible x WHERE x.emby_id=e.emby_id AND x.supported=e.supported))
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,emby_id,'emby:'||emby_id,'change_identity','replace-provider-id','linked-media-identity','tmdb',old_id,new_id,linked,checked,supported,CASE WHEN exact_or_alias=1 THEN .97 WHEN supported=checked THEN .95 ELSE .88 END,
'Dead TMDB ID '||old_id||'; unique linked-media candidate '||candidate_name||' ('||new_id||') is credited on '||supported||' of '||checked||' TMDB-resolved linked media. Current Emby name remains '||current_name,@now FROM winners
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=winners.emby_id AND h.provider='tmdb' AND h.recommendation_type='replace-provider-id')",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private sealed class RenameProviderEvidence
        {
            public string Provider; public string ExternalId; public string CanonicalName; public List<string> Aliases;
            public int Linked; public int Checked; public int Supported; public bool Collision;
        }

        private void RenamesV3(IDatabaseConnection x,long run)
        {
            const string sql=@"WITH audit AS (
SELECT person_emby_id,provider,max(linked_media_count) linked,max(checked_media_count) checked,max(supported_media_count) supported FROM housekeeping_signal WHERE run_id=@run AND signal_type IN('identity-supported','identity-partially-supported') GROUP BY person_emby_id,provider), known_names AS (SELECT lower(name) name,count(*) owners FROM emby_item WHERE item_type='person' AND name IS NOT NULL GROUP BY lower(name))
SELECT p.emby_id,p.name,
 p.tmdb_id,te.name,coalesce(ta.linked,0),coalesce(ta.checked,0),coalesce(ta.supported,0),(SELECT group_concat(alias,char(31)) FROM tmdb_alias WHERE entity_type='person' AND tmdb_id=p.tmdb_id),CASE WHEN coalesce(tk.owners,0)>CASE WHEN lower(p.name)=lower(te.name) THEN 1 ELSE 0 END THEN 1 ELSE 0 END,
 p.tvdb_id,ve.name,coalesce(va.linked,0),coalesce(va.checked,0),coalesce(va.supported,0),(SELECT group_concat(alias,char(31)) FROM tvdb_alias WHERE entity_type='person' AND tvdb_id=p.tvdb_id),CASE WHEN coalesce(vk.owners,0)>CASE WHEN lower(p.name)=lower(ve.name) THEN 1 ELSE 0 END THEN 1 ELSE 0 END
FROM emby_item p LEFT JOIN tmdb_entity te ON te.entity_type='person' AND te.tmdb_id=p.tmdb_id LEFT JOIN tvdb_entity ve ON ve.entity_type='person' AND ve.tvdb_id=p.tvdb_id LEFT JOIN audit ta ON ta.person_emby_id=p.emby_id AND ta.provider='tmdb' LEFT JOIN audit va ON va.person_emby_id=p.emby_id AND va.provider='tvdb' LEFT JOIN known_names tk ON tk.name=lower(te.name) LEFT JOIN known_names vk ON vk.name=lower(ve.name)
WHERE p.item_type='person' AND (coalesce(ta.supported,0)>0 OR coalesce(va.supported,0)>0)";
            using(var s=x.PrepareStatement(sql))
            {
                s.TryBind("@run",run);
                foreach(var row in s.ExecuteQuery())
                {
                    var embyId=row.GetInt64(0);var current=row.IsDBNull(1)?string.Empty:row.GetString(1);var providers=new List<RenameProviderEvidence>();
                    AddRenameProvider(providers,"tmdb",row,2,3,4,5,6,7,8);
                    AddRenameProvider(providers,"tvdb",row,9,10,11,12,13,14,15);
                    var healthy=providers.Where(p=>p.Supported>0&&!string.IsNullOrWhiteSpace(p.CanonicalName)).ToList();if(healthy.Count==0)continue;
                    if(healthy.Any(p=>ExactProviderName(p,current)))continue;
                    RenameProviderEvidence chosen;string provider;string consensus;
                    if(healthy.Count>1)
                    {
                        var forms=healthy.Select(p=>PersonNameCompatibility.ExactForm(p.CanonicalName)).Distinct().ToList();
                        if(forms.Count!=1)continue;
                        chosen=healthy.OrderByDescending(p=>p.Supported).ThenBy(p=>p.Provider=="tmdb"?0:1).First();provider="cross-provider";consensus="TMDB and TVDB agree on canonical name '"+chosen.CanonicalName+"'";
                    }
                    else {chosen=healthy[0];provider=chosen.Provider;consensus=chosen.Provider.ToUpperInvariant()+" supplies the only healthy media-backed canonical name";}
                    if(PersonNameCompatibility.ExactForm(current)==PersonNameCompatibility.ExactForm(chosen.CanonicalName))continue;
                    var match=PersonNameCompatibility.Compare(current,chosen.CanonicalName,healthy.SelectMany(p=>p.Aliases),Plugin.Instance.Configuration.GivenNameEquivalences);
                    var collision=healthy.Any(p=>p.Collision);var evidence=consensus+"; "+string.Join("; ",healthy.Select(p=>p.Provider.ToUpperInvariant()+" "+p.ExternalId+" supports "+p.Supported+"/"+p.Checked+" checked linked media"))+"; current/proposed compatibility: "+match.Reason+". Name compatibility corroborates this rename only and does not establish identity.";
                    Exec(x,"INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc) VALUES(@run,@emby,@subject,'update',@type,@signal,@provider,@current,@proposed,@linked,@checked,@supported,@confidence,@evidence,@now)",q=>{q.TryBind("@run",run);q.TryBind("@emby",embyId);q.TryBind("@subject","emby:"+embyId);q.TryBind("@type",collision?"review-existing-emby-person":"rename-person");q.TryBind("@signal",collision?"emby-name-collision":healthy.Count>1?"media-backed-provider-consensus-rename":"media-backed-provider-rename");q.TryBind("@provider",provider);q.TryBind("@current",current);q.TryBind("@proposed",chosen.CanonicalName);q.TryBind("@linked",healthy.Max(p=>p.Linked));q.TryBind("@checked",healthy.Max(p=>p.Checked));q.TryBind("@supported",healthy.Max(p=>p.Supported));q.TryBind("@confidence",collision?.65:healthy.Count>1?.94:(match.Compatible?.90:.82));q.TryBind("@evidence",evidence);q.TryBind("@now",Now());});
                }
            }
        }

        private static void AddRenameProvider(List<RenameProviderEvidence> target,string provider,IResultSet row,int id,int name,int linked,int checkedMedia,int supported,int aliases,int collision)
        {
            if(row.IsDBNull(id))return;target.Add(new RenameProviderEvidence{Provider=provider,ExternalId=row.GetString(id),CanonicalName=row.IsDBNull(name)?null:row.GetString(name),Linked=row.GetInt(linked),Checked=row.GetInt(checkedMedia),Supported=row.GetInt(supported),Aliases=(row.IsDBNull(aliases)?string.Empty:row.GetString(aliases)).Split(new[]{(char)31},StringSplitOptions.RemoveEmptyEntries).ToList(),Collision=row.GetInt(collision)>0});
        }

        private static bool ExactProviderName(RenameProviderEvidence provider,string current)
        {
            var form=PersonNameCompatibility.ExactForm(current);return form==PersonNameCompatibility.ExactForm(provider.CanonicalName)||provider.Aliases.Any(a=>form==PersonNameCompatibility.ExactForm(a));
        }

        private static void RenamesV2(IDatabaseConnection x,long run)=>Exec(x,@"WITH audit AS (
SELECT person_emby_id,provider,max(linked_media_count) linked,max(checked_media_count) checked,max(supported_media_count) supported FROM housekeeping_signal WHERE run_id=@run AND signal_type IN('identity-supported','identity-partially-supported') GROUP BY person_emby_id,provider), provider_names AS (
