UNION ALL SELECT p.emby_id,'tvdb',p.tvdb_id,e.name,p.name FROM emby_item p JOIN tvdb_entity e ON e.entity_type='person' AND e.tvdb_id=p.tvdb_id WHERE p.item_type='person'), name_agreement AS (
