SELECT DISTINCT person_emby_id,provider FROM candidate_media), current_media AS (
SELECT p.emby_id person_emby_id,'tmdb' provider,p.tmdb_id current_id,er.media_emby_id FROM candidate_people q JOIN emby_item p ON p.emby_id=q.person_emby_id AND q.provider='tmdb' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND c.production_type=m.item_type AND c.person_tmdb_id=p.tmdb_id
UNION ALL SELECT p.emby_id,'tvdb',p.tvdb_id,er.media_emby_id FROM candidate_people q JOIN emby_item p ON p.emby_id=q.person_emby_id AND q.provider='tvdb' JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type=m.item_type AND c.person_tvdb_id=p.tvdb_id), candidate_stats AS (
SELECT person_emby_id,provider,current_external_id current_id,candidate_external_id candidate_id,count(DISTINCT media_emby_id) candidate_media FROM candidate_media WHERE candidate_external_id<>coalesce(current_external_id,'') GROUP BY person_emby_id,provider,current_external_id,candidate_external_id), current_stats AS (
SELECT person_emby_id,provider,current_id,count(DISTINCT media_emby_id) current_media FROM current_media GROUP BY person_emby_id,provider,current_id), shared_stats AS (
SELECT c.person_emby_id,c.provider,c.candidate_external_id candidate_id,count(DISTINCT c.media_emby_id) shared_media FROM candidate_media c JOIN current_media m ON m.person_emby_id=c.person_emby_id AND m.provider=c.provider AND m.media_emby_id=c.media_emby_id WHERE c.candidate_external_id<>coalesce(c.current_external_id,'') GROUP BY c.person_emby_id,c.provider,c.candidate_external_id), partitions AS (
SELECT c.person_emby_id,c.provider,c.current_id,c.candidate_id,c.candidate_media,m.current_media,coalesce(s.shared_media,0) shared_media FROM candidate_stats c JOIN current_stats m ON m.person_emby_id=c.person_emby_id AND m.provider=c.provider LEFT JOIN shared_stats s ON s.person_emby_id=c.person_emby_id AND s.provider=c.provider AND s.candidate_id=c.candidate_id WHERE c.candidate_media>0 AND m.current_media>0 AND coalesce(s.shared_media,0)=0), grouped AS (
SELECT person_emby_id,provider,current_id,group_concat(candidate_id) ids,sum(candidate_media) candidate_media,max(current_media) current_media FROM partitions GROUP BY person_emby_id,provider,current_id)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,g.person_emby_id,'emby:'||g.person_emby_id,'split','review-split','linked-media-partition',g.provider,g.current_id,g.ids,(SELECT count(DISTINCT media_emby_id) FROM emby_relationship er WHERE er.person_emby_id=g.person_emby_id),g.current_media+g.candidate_media,g.current_media+g.candidate_media,.88,'Emby person '||g.person_emby_id||' has disjoint linked-media support for current '||upper(g.provider)||' ID '||coalesce(g.current_id,'-')||' and candidate ID(s) '||g.ids||'; review relationship partition and existing Emby ownership before creating a person',@now FROM grouped g
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=g.person_emby_id AND h.recommendation_type='review-split' AND h.provider=g.provider)",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void Splits(IDatabaseConnection x,long run)=>Exec(x,@"WITH s AS (SELECT p.emby_id,'tmdb' provider,p.tmdb_id current_id,cp.tmdb_id candidate,count(DISTINCT er.media_emby_id) media FROM emby_item p JOIN emby_item cp ON cp.item_type='person' AND cp.emby_id<>p.emby_id AND cp.name=p.name AND cp.tmdb_id IS NOT NULL JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=m.tmdb_id AND c.person_tmdb_id=cp.tmdb_id WHERE p.item_type='person' GROUP BY p.emby_id,p.tmdb_id,cp.tmdb_id UNION ALL SELECT p.emby_id,'tvdb',p.tvdb_id,cp.tvdb_id,count(DISTINCT er.media_emby_id) FROM emby_item p JOIN emby_item cp ON cp.item_type='person' AND cp.emby_id<>p.emby_id AND cp.name=p.name AND cp.tvdb_id IS NOT NULL JOIN emby_relationship er ON er.person_emby_id=p.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=m.tvdb_id AND c.person_tvdb_id=cp.tvdb_id WHERE p.item_type='person' GROUP BY p.emby_id,p.tvdb_id,cp.tvdb_id),q AS(SELECT emby_id,provider,current_id,count(*) n,sum(media) media,group_concat(candidate) ids FROM s GROUP BY emby_id,provider,current_id HAVING count(*)>1) INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,supported_media_count,confidence,evidence_summary,created_utc) SELECT @run,emby_id,'emby:'||emby_id,'split','review-split','linked-media-partition',provider,current_id,ids,media,.75,'Emby person '||emby_id||' has linked credits partitioned across multiple name-compatible '||upper(provider)||' identities; review each media relationship before creating or moving people',@now FROM q",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void CrossProviderSplits(IDatabaseConnection x,long run)=>Exec(x,@"WITH identities AS (
SELECT p.emby_id,p.name,p.tmdb_id,p.tvdb_id,p.imdb_id,te.name tmdb_name,json_extract(te.raw_json,'$.external_ids.imdb_id') tmdb_imdb,rt.remote_id tvdb_tmdb,ri.remote_id tvdb_imdb,(SELECT s.candidate_external_id FROM housekeeping_signal s JOIN remote_id ct ON ct.entity_type='person' AND ct.tvdb_id=s.candidate_external_id AND ct.source_name='TheMovieDB.com' AND ct.remote_id=p.tmdb_id JOIN remote_id ci ON ci.entity_type='person' AND ci.tvdb_id=s.candidate_external_id AND ci.source_name='IMDB' AND ci.remote_id=coalesce(p.imdb_id,json_extract(te.raw_json,'$.external_ids.imdb_id')) WHERE s.run_id=@run AND s.person_emby_id=p.emby_id AND s.provider='tvdb' AND s.signal_type LIKE 'confirmed-%' GROUP BY s.candidate_external_id ORDER BY count(DISTINCT s.media_emby_id) DESC LIMIT 1) retain_tvdb
FROM emby_item p JOIN tmdb_entity te ON te.entity_type='person' AND te.tmdb_id=p.tmdb_id JOIN tvdb_entity ve ON ve.entity_type='person' AND ve.tvdb_id=p.tvdb_id JOIN remote_id rt ON rt.entity_type='person' AND rt.tvdb_id=p.tvdb_id AND rt.source_name='TheMovieDB.com' AND rt.remote_id<>p.tmdb_id JOIN remote_id ri ON ri.entity_type='person' AND ri.tvdb_id=p.tvdb_id AND ri.source_name='IMDB' AND ri.remote_id<>coalesce(p.imdb_id,json_extract(te.raw_json,'$.external_ids.imdb_id')) WHERE p.item_type='person' AND p.tmdb_id IS NOT NULL AND p.tvdb_id IS NOT NULL), tmdb_supported AS (
SELECT DISTINCT i.emby_id,er.media_emby_id FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND c.production_type=m.item_type AND c.person_tmdb_id=i.tmdb_id), tvdb_supported AS (
SELECT DISTINCT i.emby_id,er.media_emby_id FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id JOIN tvdb_credit_observation c ON c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type=m.item_type AND c.person_tvdb_id=i.tvdb_id), tmdb_stats AS (
SELECT emby_id,count(*) media FROM tmdb_supported GROUP BY emby_id), tvdb_stats AS (
SELECT emby_id,count(*) media FROM tvdb_supported GROUP BY emby_id), shared_stats AS (
SELECT t.emby_id,count(*) media FROM tmdb_supported t JOIN tvdb_supported v ON v.emby_id=t.emby_id AND v.media_emby_id=t.media_emby_id GROUP BY t.emby_id), linked_stats AS (
SELECT i.emby_id,count(DISTINCT er.media_emby_id) media FROM identities i JOIN emby_relationship er ON er.person_emby_id=i.emby_id GROUP BY i.emby_id), support AS (
SELECT i.*,coalesce(t.media,0) tmdb_media,coalesce(v.media,0) tvdb_media,coalesce(s.media,0) shared_media,coalesce(l.media,0) linked,(SELECT group_concat(m.name,', ') FROM tmdb_supported z JOIN emby_item m ON m.emby_id=z.media_emby_id WHERE z.emby_id=i.emby_id) tmdb_titles,(SELECT group_concat(m.name,', ') FROM tvdb_supported z JOIN emby_item m ON m.emby_id=z.media_emby_id WHERE z.emby_id=i.emby_id) tvdb_titles FROM identities i LEFT JOIN tmdb_stats t ON t.emby_id=i.emby_id LEFT JOIN tvdb_stats v ON v.emby_id=i.emby_id LEFT JOIN shared_stats s ON s.emby_id=i.emby_id LEFT JOIN linked_stats l ON l.emby_id=i.emby_id), eligible AS (
SELECT * FROM support WHERE tvdb_tmdb IS NOT NULL AND tvdb_tmdb<>tmdb_id AND tvdb_imdb IS NOT NULL AND coalesce(imdb_id,tmdb_imdb,'')<>'' AND tvdb_imdb<>coalesce(imdb_id,tmdb_imdb) AND tmdb_media>0 AND tvdb_media>0 AND shared_media=0)
INSERT INTO housekeeping_recommendation(run_id,person_emby_id,subject_truth_entity_id,operation,recommendation_type,primary_signal_type,provider,current_value,proposed_value,linked_media_count,checked_media_count,supported_media_count,confidence,evidence_summary,created_utc)
SELECT @run,emby_id,'emby:'||emby_id,'split','review-split','cross-provider-media-partition','cross-provider','TMDB='||tmdb_id||'; TVDB='||tvdb_id||'; IMDb='||coalesce(imdb_id,tmdb_imdb,'-'),json_object('retain_tmdb',tmdb_id,'retain_tvdb',retain_tvdb,'retain_imdb',coalesce(imdb_id,tmdb_imdb),'split_tmdb',tvdb_tmdb,'split_tvdb',tvdb_id,'split_imdb',tvdb_imdb),linked,tmdb_media+tvdb_media,tmdb_media+tvdb_media,.97,
'Actionable identity/media partition for Emby '||emby_id||' '||name||'. Retain cluster: TMDB '||tmdb_id||' / TVDB '||coalesce(retain_tvdb,'-')||' / IMDb '||coalesce(imdb_id,tmdb_imdb,'-')||' on ['||coalesce(tmdb_titles,'')||']. Create a new Emby person and move ['||coalesce(tvdb_titles,'')||'] to split cluster: TMDB '||tvdb_tmdb||' / TVDB '||tvdb_id||' / IMDb '||tvdb_imdb||'. Provider-native supported media are disjoint; shared supported media='||shared_media||'. The reviewer chooses the survivor if library context requires a different disposition.',@now FROM eligible
WHERE NOT EXISTS(SELECT 1 FROM housekeeping_recommendation h WHERE h.run_id=@run AND h.person_emby_id=eligible.emby_id AND h.recommendation_type='review-split' AND h.primary_signal_type='cross-provider-media-partition')",s=>{s.TryBind("@run",run);s.TryBind("@now",Now());});

        private static void ConsolidateReviewCases(IDatabaseConnection x,long run)
        {
            Exec(x,@"WITH collision_merge AS (
SELECT r.recommendation_id,r.person_emby_id source_id,o.emby_id owner_id,p.tmdb_id identity_id,p.name source_name,o.name owner_name,m.name media_name
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id JOIN emby_item o ON o.item_type='person' AND o.emby_id<>p.emby_id AND lower(o.name)=lower(r.proposed_value) JOIN emby_relationship er ON er.person_emby_id=o.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN tmdb_item_resolution mr ON mr.emby_id=m.emby_id JOIN tmdb_credit_observation c ON r.provider='tmdb' AND c.production_tmdb_id=coalesce(m.tmdb_id,mr.resolved_tmdb_id) AND c.production_type=m.item_type AND c.person_tmdb_id=p.tmdb_id
WHERE r.run_id=@run AND r.recommendation_type='review-existing-emby-person' AND p.tmdb_id IS NOT NULL
UNION ALL
SELECT r.recommendation_id,r.person_emby_id,o.emby_id,p.tvdb_id,p.name,o.name,m.name
FROM housekeeping_recommendation r JOIN emby_item p ON p.emby_id=r.person_emby_id JOIN emby_item o ON o.item_type='person' AND o.emby_id<>p.emby_id AND lower(o.name)=lower(r.proposed_value) JOIN emby_relationship er ON er.person_emby_id=o.emby_id JOIN emby_item m ON m.emby_id=er.media_emby_id LEFT JOIN item_resolution mr ON mr.emby_id=m.emby_id JOIN tvdb_credit_observation c ON r.provider='tvdb' AND c.production_tvdb_id=coalesce(m.tvdb_id,mr.resolved_tvdb_id) AND c.production_type=m.item_type AND c.person_tvdb_id=p.tvdb_id
WHERE r.run_id=@run AND r.recommendation_type='review-existing-emby-person' AND p.tvdb_id IS NOT NULL)
UPDATE housekeeping_recommendation SET person_emby_id=(SELECT min(source_id,owner_id) FROM collision_merge WHERE recommendation_id=housekeeping_recommendation.recommendation_id),subject_truth_entity_id='emby:'||(SELECT min(source_id,owner_id) FROM collision_merge WHERE recommendation_id=housekeeping_recommendation.recommendation_id),operation='merge',recommendation_type='review-merge',primary_signal_type='cross-emby-exact-media-identity',current_value=(SELECT CASE WHEN source_id<owner_id THEN source_id||','||owner_id ELSE owner_id||','||source_id END FROM collision_merge WHERE recommendation_id=housekeeping_recommendation.recommendation_id),proposed_value=(SELECT identity_id FROM collision_merge WHERE recommendation_id=housekeeping_recommendation.recommendation_id),confidence=.92,evidence_summary=(SELECT 'Review merge Emby '||source_id||' '||source_name||' and Emby '||owner_id||' '||owner_name||'. The healthy '||upper(housekeeping_recommendation.provider)||' identity '||identity_id||' proposes the existing canonical name and has exact provider-native support on media linked to the other Emby record: '||media_name||'. Show both people, all identities and all linked media before choosing a survivor.' FROM collision_merge WHERE recommendation_id=housekeeping_recommendation.recommendation_id) WHERE recommendation_id IN(SELECT recommendation_id FROM collision_merge)",s=>s.TryBind("@run",run));
            Exec(x,@"WITH candidate_stats AS (
SELECT person_emby_id,provider,current_external_id,candidate_external_id,count(DISTINCT media_emby_id) linked,count(DISTINCT CASE WHEN signal_type IN('confirmed-exact-scope','confirmed-broader-series-scope','not-present') THEN media_emby_id END) checked,count(DISTINCT CASE WHEN signal_type LIKE 'confirmed-%' THEN media_emby_id END) supported FROM housekeeping_signal WHERE run_id=@run AND media_emby_id IS NOT NULL GROUP BY person_emby_id,provider,current_external_id,candidate_external_id), strong AS (
SELECT r.recommendation_id,r.person_emby_id,r.current_value,r.proposed_value,c.linked,c.checked,c.supported,cur.supported current_supported,p.name,p.tmdb_id,coalesce(p.imdb_id,tx.external_id) imdb_id,
(SELECT group_concat(m.name,', ') FROM housekeeping_signal s JOIN emby_item m ON m.emby_id=s.media_emby_id WHERE s.run_id=@run AND s.person_emby_id=r.person_emby_id AND s.provider='tvdb' AND s.candidate_external_id=r.current_value AND s.signal_type LIKE 'confirmed-%') outlier_titles
FROM housekeeping_recommendation r JOIN candidate_stats c ON c.person_emby_id=r.person_emby_id AND c.provider='tvdb' AND c.candidate_external_id=r.proposed_value LEFT JOIN candidate_stats cur ON cur.person_emby_id=r.person_emby_id AND cur.provider='tvdb' AND cur.candidate_external_id=r.current_value JOIN emby_item p ON p.emby_id=r.person_emby_id LEFT JOIN tmdb_external_id tx ON tx.entity_type='person' AND tx.tmdb_id=p.tmdb_id AND tx.source_name='imdb' JOIN remote_id nt ON nt.entity_type='person' AND nt.tvdb_id=r.proposed_value AND nt.source_name='TheMovieDB.com' AND nt.remote_id=p.tmdb_id JOIN remote_id ni ON ni.entity_type='person' AND ni.tvdb_id=r.proposed_value AND ni.source_name='IMDB' AND ni.remote_id=coalesce(p.imdb_id,tx.external_id) JOIN remote_id ot ON ot.entity_type='person' AND ot.tvdb_id=r.current_value AND ot.source_name='TheMovieDB.com' AND ot.remote_id<>p.tmdb_id JOIN remote_id oi ON oi.entity_type='person' AND oi.tvdb_id=r.current_value AND oi.source_name='IMDB' AND oi.remote_id<>coalesce(p.imdb_id,tx.external_id) JOIN emby_item owner ON owner.item_type='person' AND owner.emby_id<>p.emby_id AND owner.tvdb_id=r.current_value AND owner.tmdb_id=ot.remote_id AND coalesce(owner.imdb_id,oi.remote_id)=oi.remote_id
WHERE r.run_id=@run AND r.recommendation_type='replace-provider-id' AND r.provider='tvdb' AND c.supported>=cast((c.linked*8+9)/10 AS integer) AND coalesce(cur.supported,0)<=1)
UPDATE housekeeping_recommendation SET primary_signal_type='provider-credit-misattribution',linked_media_count=(SELECT linked FROM strong WHERE recommendation_id=housekeeping_recommendation.recommendation_id),checked_media_count=(SELECT checked FROM strong WHERE recommendation_id=housekeeping_recommendation.recommendation_id),supported_media_count=(SELECT supported FROM strong WHERE recommendation_id=housekeeping_recommendation.recommendation_id),evidence_summary=(SELECT 'Replace TVDB '||current_value||' with '||proposed_value||' for Emby '||person_emby_id||' '||name||'. Candidate TVDB identity matches healthy TMDB '||tmdb_id||' / IMDb '||imdb_id||' and has exact provider-native support on '||supported||'/'||linked||' linked media. Current TVDB identity supports only '||current_supported||'/'||linked||' and belongs to a separately coherent Emby person; its isolated credit on ['||coalesce(outlier_titles,'')||'] is retained as likely provider-credit misattribution evidence, not split or merge evidence.' FROM strong WHERE recommendation_id=housekeeping_recommendation.recommendation_id) WHERE recommendation_id IN(SELECT recommendation_id FROM strong)",s=>s.TryBind("@run",run));

            Exec(x,@"DELETE FROM housekeeping_recommendation AS r WHERE r.run_id=@run AND r.recommendation_type='review-split' AND r.provider<>'cross-provider' AND EXISTS(SELECT 1 FROM housekeeping_recommendation a WHERE a.run_id=r.run_id AND a.person_emby_id=r.person_emby_id AND (a.primary_signal_type='cross-provider-media-partition' OR (a.recommendation_type='replace-provider-id' AND a.provider=r.provider)))",s=>s.TryBind("@run",run));
            Exec(x,@"DELETE FROM housekeeping_recommendation AS r WHERE r.run_id=@run AND r.recommendation_type='review-unresolved-provider-id' AND EXISTS(SELECT 1 FROM housekeeping_recommendation a WHERE a.run_id=r.run_id AND a.person_emby_id=r.person_emby_id AND (a.provider=r.provider OR a.provider='cross-provider') AND a.recommendation_type IN('replace-provider-id','review-merge','review-split'))",s=>s.TryBind("@run",run));
            Exec(x,@"DELETE FROM housekeeping_recommendation AS m WHERE m.run_id=@run AND m.recommendation_type='review-merge' AND EXISTS(SELECT 1 FROM housekeeping_recommendation r WHERE r.run_id=m.run_id AND r.recommendation_type='replace-provider-id' AND r.provider=m.provider AND r.current_value=m.proposed_value AND (','||m.current_value||',') LIKE '%,'||r.person_emby_id||',%')",s=>s.TryBind("@run",run));
            Exec(x,@"DELETE FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='provider-person-split-error'",s=>s.TryBind("@run",run));
        }

        private static void DeltaTruth(IDatabaseConnection x,long run){Exec(x,"INSERT INTO truth(name,parent_truth_id,created_utc,status,description) VALUES(@name,1,@now,'frozen',@description)",s=>{s.TryBind("@name","Person housekeeping delta run "+run);s.TryBind("@now",Now());s.TryBind("@description","Delta truth from normalized-v9 run "+run);});long truth=LastId(x);Exec(x,"INSERT OR REPLACE INTO truth_entity_delta SELECT @truth,subject_truth_entity_id,'update',proposed_value,'update','housekeeping-run:'||@run FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type='rename-person' ORDER BY CASE provider WHEN 'tmdb' THEN 1 ELSE 0 END",s=>{s.TryBind("@truth",truth);s.TryBind("@run",run);});Exec(x,"INSERT OR REPLACE INTO truth_identity_delta SELECT @truth,subject_truth_entity_id,provider,CASE recommendation_type WHEN 'remove-provider-id' THEN 'remove' ELSE 'set' END,proposed_value,'housekeeping-run:'||@run FROM housekeeping_recommendation WHERE run_id=@run AND recommendation_type IN('remove-provider-id','replace-provider-id') ORDER BY confidence",s=>{s.TryBind("@truth",truth);s.TryBind("@run",run);});Exec(x,"UPDATE housekeeping_run SET derived_truth_id=@truth,phase='delta-truth',progress=96,heartbeat_utc=@now WHERE run_id=@run",s=>{s.TryBind("@truth",truth);s.TryBind("@now",Now());s.TryBind("@run",run);});}
        private static void Complete(IDatabaseConnection x,long run){var now=Now();Exec(x,"INSERT INTO experiment_metric SELECT @run,'person',recommendation_type,'recommendation_count',count(*) FROM housekeeping_recommendation WHERE run_id=@run GROUP BY recommendation_type",s=>s.TryBind("@run",run));Exec(x,"UPDATE housekeeping_run SET phase='completed',progress=100,status='completed',heartbeat_utc=@now,completed_utc=@now WHERE run_id=@run",s=>{s.TryBind("@now",now);s.TryBind("@run",run);});Exec(x,"UPDATE experiment_run SET status='completed',completed_utc=@now WHERE run_id=@run",s=>{s.TryBind("@now",now);s.TryBind("@run",run);});}
        private void Stop(long run,string status,string error){try{Tx(x=>{Exec(x,"UPDATE housekeeping_run SET status=@s,phase=@s,heartbeat_utc=@now,completed_utc=@now,error=@e WHERE run_id=@run",q=>{q.TryBind("@s",status);q.TryBind("@now",Now());q.TryBind("@e",error);q.TryBind("@run",run);});Exec(x,"UPDATE experiment_run SET status=@s,completed_utc=@now WHERE run_id=@run",q=>{q.TryBind("@s",status);q.TryBind("@now",Now());q.TryBind("@run",run);});});}catch{}}

        public List<HousekeepingResultRow> LatestResults(){var a=new List<HousekeepingResultRow>();const string sql=@"WITH RECURSIVE base AS (
SELECT r.*,CASE WHEN r.recommendation_type='review-merge' THEN CASE WHEN instr(r.proposed_value,',')>0 THEN r.proposed_value ELSE r.current_value END ELSE cast(r.person_emby_id AS text) END participant_ids
FROM housekeeping_latest_results r), parts(recommendation_id,rest,person_id) AS (
SELECT recommendation_id,participant_ids||',','' FROM base
UNION ALL SELECT recommendation_id,substr(rest,instr(rest,',')+1),substr(rest,1,instr(rest,',')-1) FROM parts WHERE rest<>''), participants AS (
SELECT recommendation_id,cast(person_id AS integer) person_id FROM parts WHERE person_id<>''), identity_agg AS (
SELECT p.recommendation_id,
 group_concat('Emby '||e.emby_id||': '||e.name,' | ') names,
 group_concat('Emby '||e.emby_id||': '||coalesce(e.tmdb_id,'-'),' | ') tmdb_ids,
 group_concat('Emby '||e.emby_id||': '||coalesce(e.tvdb_id,'-'),' | ') tvdb_ids,
 group_concat('Emby '||e.emby_id||': '||CASE WHEN e.imdb_id IS NOT NULL THEN e.imdb_id WHEN tx.external_id IS NOT NULL THEN 'TMDB '||e.tmdb_id||' -> '||tx.external_id ELSE '-' END,' | ') imdb_ids
FROM participants p JOIN emby_item e ON e.emby_id=p.person_id LEFT JOIN tmdb_external_id tx ON tx.tmdb_id=e.tmdb_id AND tx.entity_type='person' AND tx.source_name='imdb' GROUP BY p.recommendation_id), media_agg AS (
SELECT p.recommendation_id,group_concat('Emby '||er.person_emby_id||' -> media '||er.media_emby_id||' '||coalesce(m.name,'')||' ['||coalesce(er.person_type,'')||coalesce(': '||er.role,'')||']',' | ') media
FROM participants p JOIN base b ON b.recommendation_id=p.recommendation_id AND b.recommendation_type IN('review-merge','review-split') JOIN emby_relationship er ON er.person_emby_id=p.person_id LEFT JOIN emby_item m ON m.emby_id=er.media_emby_id GROUP BY p.recommendation_id), signal_media AS (
SELECT b.recommendation_id,group_concat(s.evidence_text,' | ') media FROM base b JOIN housekeeping_signal s ON s.run_id=b.run_id AND s.person_emby_id=b.person_emby_id AND (s.provider=b.provider OR b.provider='cross-provider') AND s.media_emby_id IS NOT NULL AND (b.recommendation_type NOT IN('review-split','review-merge') OR s.signal_type LIKE 'confirmed-%') AND (b.provider='cross-provider' OR s.candidate_external_id IS NULL OR (','||coalesce(b.proposed_value,'')||',') LIKE '%,'||s.candidate_external_id||',%' OR b.current_value LIKE '%'||s.candidate_external_id||'%') GROUP BY b.recommendation_id)
SELECT r.recommendation_id,r.person_emby_id,r.person,r.recommendation_type,r.primary_signal_type,r.provider,r.current_value,r.proposed_value,r.confidence,r.linked_media_count,r.checked_media_count,r.evidence_summary,r.review_status,r.participant_ids,
CASE WHEN r.recommendation_type='review-merge' THEN 'Reviewer must select one of: '||r.participant_ids WHEN r.recommendation_type='review-split' THEN r.person_emby_id||' plus new Emby person(s)' ELSE cast(r.person_emby_id AS text) END proposed_emby,
coalesce(i.names,'') current_name,
CASE WHEN r.recommendation_type IN('rename-person','review-existing-emby-person') THEN coalesce(r.proposed_value,'') ELSE coalesce(i.names,'') END proposed_name,
coalesce(i.tmdb_ids,'') current_tmdb,
CASE WHEN r.provider='cross-provider' AND r.recommendation_type='review-split' THEN 'Retain '||coalesce(json_extract(r.proposed_value,'$.retain_tmdb'),'-')||' | Split '||coalesce(json_extract(r.proposed_value,'$.split_tmdb'),'-') WHEN r.provider='tmdb' AND r.recommendation_type='remove-provider-id' THEN '(remove)' WHEN r.provider='tmdb' AND r.recommendation_type IN('replace-provider-id','review-split','review-unresolved-provider-id','provider-person-split-error') THEN coalesce(CASE WHEN r.recommendation_type='provider-person-split-error' THEN r.current_value ELSE r.proposed_value END,'-') WHEN r.provider='tmdb' AND r.recommendation_type='review-merge' THEN coalesce(CASE WHEN instr(r.proposed_value,',')>0 THEN r.current_value ELSE r.proposed_value END,'-') ELSE coalesce(i.tmdb_ids,'') END proposed_tmdb,
coalesce(i.tvdb_ids,'') current_tvdb,
CASE WHEN r.provider='cross-provider' AND r.recommendation_type='review-split' THEN 'Retain '||coalesce(json_extract(r.proposed_value,'$.retain_tvdb'),'-')||' | Split '||coalesce(json_extract(r.proposed_value,'$.split_tvdb'),'-') WHEN r.provider='tvdb' AND r.recommendation_type='remove-provider-id' THEN '(remove)' WHEN r.provider='tvdb' AND r.recommendation_type IN('replace-provider-id','review-split','review-unresolved-provider-id','provider-person-split-error') THEN coalesce(CASE WHEN r.recommendation_type='provider-person-split-error' THEN r.current_value ELSE r.proposed_value END,'-') WHEN r.provider='tvdb' AND r.recommendation_type='review-merge' THEN coalesce(CASE WHEN instr(r.proposed_value,',')>0 THEN r.current_value ELSE r.proposed_value END,'-') ELSE coalesce(i.tvdb_ids,'') END proposed_tvdb,
coalesce(i.imdb_ids,'') current_imdb,CASE WHEN r.provider='cross-provider' AND r.recommendation_type='review-split' THEN 'Retain '||coalesce(json_extract(r.proposed_value,'$.retain_imdb'),'-')||' | Split '||coalesce(json_extract(r.proposed_value,'$.split_imdb'),'-') ELSE coalesce(i.imdb_ids,'') END proposed_imdb,coalesce(sm.media,m.media,'') media
FROM base r LEFT JOIN identity_agg i ON i.recommendation_id=r.recommendation_id LEFT JOIN media_agg m ON m.recommendation_id=r.recommendation_id LEFT JOIN signal_media sm ON sm.recommendation_id=r.recommendation_id ORDER BY r.confidence DESC,r.recommendation_id";using(var s=db.PrepareStatement(sql))foreach(var r in s.ExecuteQuery())a.Add(new HousekeepingResultRow{ProposalId=r.GetInt64(0),EmbyPersonId=r.GetInt64(1),Person=T(r,2),Recommendation=T(r,3),SignalType=T(r,4),Provider=T(r,5),CurrentValue=T(r,6),ProposedValue=T(r,7),Confidence=r.IsDBNull(8)?0:r.GetDouble(8),LinkedMedia=r.IsDBNull(9)?0:r.GetInt(9),CheckedMedia=r.IsDBNull(10)?0:r.GetInt(10),Evidence=T(r,11),ReviewStatus=T(r,12),CurrentEmbyIds=T(r,13),ProposedEmbyIds=T(r,14),CurrentName=T(r,15),ProposedName=T(r,16),CurrentTmdbIds=T(r,17),ProposedTmdbIds=T(r,18),CurrentTvdbIds=T(r,19),ProposedTvdbIds=T(r,20),CurrentImdbIds=T(r,21),ProposedImdbIds=T(r,22),LinkedMediaEvidence=T(r,23)});return a;}
        public string LatestRunSummary(){using(var s=db.PrepareStatement("SELECT 'Latest completed run '||run_id||' | algorithm '||algorithm_version||' | base truth '||base_truth_id||' | observations through '||observation_cutoff_utc||' | completed '||coalesce(completed_utc,'-') FROM housekeeping_run WHERE status='completed' ORDER BY run_id DESC LIMIT 1"))foreach(var r in s.ExecuteQuery())return T(r,0);return "No completed housekeeping run";}
        private void Tx(Action<IDatabaseConnection>a)=>db.RunInTransaction(a,TransactionMode.Immediate);
        private static void State(IDatabaseConnection x,long run,string phase,double progress)=>Exec(x,"UPDATE housekeeping_run SET phase=@p,progress=@n,heartbeat_utc=@now WHERE run_id=@run",s=>{s.TryBind("@p",phase);s.TryBind("@n",progress);s.TryBind("@now",Now());s.TryBind("@run",run);});
        private static void Phase(CancellationToken t,Action<string,double,TimeSpan>r,Stopwatch c,string n,double p){t.ThrowIfCancellationRequested();r?.Invoke(n,p,c.Elapsed);}
        private long Scalar(string sql)=>Scalar(db,sql,s=>{}); private static long Scalar(IDatabaseConnection x,string sql,Action<IStatement>b){using(var s=x.PrepareStatement(sql)){b(s);foreach(var r in s.ExecuteQuery())return r.IsDBNull(0)?0:r.GetInt64(0);}return 0;}
        private static long LastId(IDatabaseConnection x)=>Scalar(x,"SELECT last_insert_rowid()",s=>{}); private static string T(IResultSet r,int i)=>r.IsDBNull(i)?"":r.GetString(i);
        private static void Exec(IDatabaseConnection x,string sql,Action<IStatement>b){using(var s=x.PrepareStatement(sql)){b(s);s.MoveNext();}} private static string Now()=>DateTime.UtcNow.ToString("o"); public void Dispose()=>db.Dispose();
    }
}
